50	// =========================================================================
51	// Strategy-agnostic helper functions
52	// =========================================================================
53	
54	__aicore__ inline int32_t BlockCountHelper(int32_t M, int32_t blockM)
55	{
56	    if (blockM == 0) { return 0; }
57	    return (M + blockM - 1) / blockM;
58	}
59	
60	template <typename T>
61	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
62	{
63	    if constexpr (std::is_same_v<T, bfloat16_t>) {
64	        return AscendC::RoundMode::CAST_ROUND;
65	    }
66	    return AscendC::RoundMode::CAST_NONE;
67	}
