111	template <typename T>
112	__aicore__ inline void FinalizeOutputTensorHelper(
113	    AscendC::LocalTensor<T> &out,
114	    AscendC::LocalTensor<float> &src,
115	    int32_t count)
116	{
117	    if constexpr (!std::is_same_v<T, float>) {
118	        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
119	        AscendC::PipeBarrier<PIPE_V>();
120	    }
121	}
