11	// ============================================================
12	// Isamax op_kernel
13	// BLAS Level 1: 实数向量最大绝对值索引查找
14	// 计算: argmax_i |x[i*incx]|, 返回 1-based int32 索引
15	// 支持: float32, float16
16	// ============================================================
17	
18	#include "kernel_operator.h"
19	
20	constexpr int32_t BUFFER_NUM = 2;
21	
22	template <typename T>
23	class KernelIsamax {
24	public:
25	    __aicore__ inline KernelIsamax() {}
26	
27	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR output,
28	                                 int64_t totalLength, int64_t incx,
29	                                 int64_t tileLength)
30	    {
31	        this->totalLength = totalLength;
32	        this->incx = incx;
33	        this->tileLength = tileLength;
34	        this->maxVal = -3.402823466e+38f;  // float32 负无穷
35	        this->maxIdx = -1;
36	
