// Snrm2 op_kernel
// BLAS Level 1: Euclidean norm sqrt(sum(x[i*incx]^2))
// Supports float32, float16
// Uses multi-core partial sum computation, host-side final reduction

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelSnrm2 {
public:
    __aicore__ inline KernelSnrm2() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR workspace,
                                 int64_t totalLength, int64_t incx,
                                 int64_t tileLength, int64_t needCast)
    {
        this->totalLength = totalLength;
        this->incx = incx;
        this->tileLength = tileLength;
        this->needCast = needCast;
        this->partialSum = 0.0f;

        int64_t physCount = tileLength * incx;

        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), totalLength * incx);
        wsGm.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(workspace), 1);

        // UB: input buffer (double-buffered)
        pipe.InitBuffer(inQueueX, BUFFER_NUM, physCount * sizeof(T));

        // UB: intermediate buffers for compute
        pipe.InitBuffer(sqBuf, physCount * sizeof(float));

        // UB: cast buffer for fp16->fp32
        if (this->needCast != 0) {
            pipe.InitBuffer(castBuf, physCount * sizeof(float));
        }

        // UB: partial sum buffer (1 float)
        pipe.InitBuffer(sumBuf, 16 * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->totalLength + this->tileLength - 1) / this->tileLength;

        // Phase 1: Per-core partial sum computation
        this->partialSum = 0.0f;

        for (int64_t i = 0; i < tileNum; ++i) {
            int64_t tileStart = i * this->tileLength;
            int64_t curTileLen = this->tileLength;
            if (i == tileNum - 1) {
                curTileLen = this->totalLength - tileStart;
            }
            int64_t physCount = curTileLen * this->incx;

            CopyIn(tileStart, physCount);
            Compute(curTileLen, physCount);
        }

        // Phase 2: Write partial sum to workspace
        WriteWorkspace();
    }

private:
    __aicore__ inline void CopyIn(int64_t tileStart, int64_t physCount)
    {
        int64_t gmOffset = tileStart * this->incx;

        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(physCount * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
        AscendC::DataCopyPad(xLocal, xGm[gmOffset], copyParams, padParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t curTileLen, int64_t physCount)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();

        AscendC::LocalTensor<float> xFloat;
        AscendC::LocalTensor<float> sqLocal = sqBuf.Get<float>();

        // Get float32 view of input data
        if constexpr (std::is_same_v<T, float>) {
            xFloat = xLocal.ReinterpretCast<float>();
        } else {
            xFloat = castBuf.Get<float>();
            AscendC::Cast(xFloat, xLocal, AscendC::RoundMode::CAST_NONE, static_cast<uint32_t>(physCount));
        }

        // Compute sum of squares for this tile
        if (this->incx == 1) {
            // Contiguous case: use vectorized Mul + ReduceSum
            AscendC::Mul(sqLocal, xFloat, xFloat, static_cast<uint32_t>(curTileLen));

            AscendC::LocalTensor<float> sumLocal = sumBuf.Get<float>();
            const uint32_t reduceShape[2] = {1U, static_cast<uint32_t>(curTileLen)};
            AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
                sumLocal, sqLocal, sqLocal[0], reduceShape, true);

            this->partialSum += sumLocal.GetValue(0);
        } else {
            // Strided case: use GetValue for strided access
            float tileSum = 0.0f;
            int64_t stride = this->incx;
            for (int64_t j = 0; j < curTileLen; ++j) {
                int64_t physIdx = j * stride;
                float val = xFloat.GetValue(static_cast<int32_t>(physIdx));
                tileSum += val * val;
            }
            this->partialSum += tileSum;
        }

        inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline void WriteWorkspace()
    {
        AscendC::LocalTensor<float> sumLocal = sumBuf.Get<float>();
        sumLocal.SetValue(0, this->partialSum);

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(sizeof(float)), 0, 0, 0};
        AscendC::DataCopyPad(wsGm, sumLocal, copyParams);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sqBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<float> wsGm;

    int64_t totalLength;
    int64_t incx;
    int64_t tileLength;
    int64_t needCast;
    float partialSum;
};

