// Snrm2 op_host — tiling + kernel launch + host-side workspace reduction
// Multi-core: each core computes partial sum → workspace[coreId]
// Host: sums workspace entries, sqrt, writes output

#include <algorithm>
#include <cmath>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_snrm2_float.h"
#include "aclrtlaunch_snrm2_half.h"

namespace ascend_kernel {

at::Tensor snrm2(const at::Tensor &x, int64_t n, int64_t incx)
{
    TORCH_CHECK(x.dim() == 1, "x must be 1D");
    TORCH_CHECK(n >= 0, "n must be non-negative");
    TORCH_CHECK(incx >= 1, "incx must be >= 1");
    TORCH_CHECK(x.numel() >= n * incx, "x too small for n*incx");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf,
        "x must be float32 or float16");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    // Platform info
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    if (coreNum <= 0) {
        coreNum = 32;
    }
    int64_t numCores = std::min(coreNum, n > 0 ? n : static_cast<int64_t>(1));

    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    int64_t dtypeSize = static_cast<int64_t>(x.element_size());
    int64_t needCast = (dtypeSize == 2) ? static_cast<int64_t>(1) : static_cast<int64_t>(0);

    // Tiling: UB allocation
    // For float32: 2*input (double buffer) + 1*sq + 1*sum
    // For float16: 2*input + 1*sq + 1*cast + 1*sum
    int64_t bufferCoefficient;
    if (needCast != 0) {
        // fp16: inQueue (2*tile*incx*2) + sqBuf (tile*4) + castBuf (tile*incx*4) + sumBuf (16*4)
        // Approximate: UB ~= 4 * tile * incx * 2 (input, double) + 4 * tile * 4 (sq) + 4 * tile * incx * 4 (cast)
        bufferCoefficient = 2 * incx * 2 + 4 + incx * 4 + 1;
    } else {
        // fp32: inQueue (2*tile*incx*4) + sqBuf (tile*4) + sumBuf (16*4)
        bufferCoefficient = 2 * incx * 4 + 4 + 1;
    }

    int64_t tileLength = static_cast<int64_t>(ubSize) / (bufferCoefficient * 4);
    // Ensure tileLength is at least 1 and 32B-aligned in float32 units (8 floats = 32 bytes)
    if (tileLength < 64) {
        tileLength = 64;
    }
    tileLength = std::min(tileLength, n > 0 ? n : static_cast<int64_t>(1));

    // Output: scalar tensor (0-dim)
    auto output = at::empty({}, x.options());

    // Workspace: one float32 per core for partial sums
    auto workspace = at::empty({numCores}, at::TensorOptions().dtype(at::kFloat).device(x.device()));

    // All params as left values for EXEC_KERNEL_CMD
    uint32_t blockDim = static_cast<uint32_t>(numCores);
    int64_t totalLength = n;
    int64_t strideVal = incx;
    int64_t tileLen = tileLength;
    int64_t castFlag = needCast;

    // Launch kernel: one block per core, each writes partial sum to its workspace slot
    uint32_t workspaceShift = 0;
    for (int64_t coreIdx = 0; coreIdx < numCores; ++coreIdx) {
        // Each core processes chunk: elements [start, end)
        int64_t chunkSize = (n + numCores - 1) / numCores;
        int64_t localStart = coreIdx * chunkSize;
        int64_t localEnd = std::min(localStart + chunkSize, n);
        int64_t localN = localEnd - localStart;

        if (localN <= 0) {
            continue;
        }

        // Point workspace to this core's slot
        auto wsPtr = workspace.data_ptr<float>() + coreIdx;

        // Adjust x pointer for this core's starting position
        auto xPtr = reinterpret_cast<void *>(
            reinterpret_cast<char *>(x.data_ptr()) + localStart * incx * dtypeSize);

        // Launch single-core kernel
        if (x.scalar_type() == at::kHalf) {
            EXEC_KERNEL_CMD(snrm2_half, 1U,
                            xPtr, wsPtr, localN, strideVal, tileLen, castFlag);
        } else {
            EXEC_KERNEL_CMD(snrm2_float, 1U,
                            xPtr, wsPtr, localN, strideVal, tileLen, castFlag);
        }
    }

    // Host-side workspace reduction
    auto wsCpu = workspace.cpu();
    auto wsAcc = wsCpu.accessor<float, 1>();
    float globalSum = 0.0f;
    for (int64_t i = 0; i < numCores; ++i) {
        globalSum += wsAcc[i];
    }
    float result = std::sqrt(globalSum);

    // Write result to output tensor on device
    if (x.scalar_type() == at::kHalf) {
        auto outCpu = output.cpu();
        outCpu.fill_(static_cast<at::Half>(result));
        output.copy_(outCpu.to(x.device()));
    } else {
        auto outCpu = output.cpu();
        outCpu.fill_(result);
        output.copy_(outCpu.to(x.device()));
    }

    return output.squeeze(-1);
}

}  // namespace ascend_kernel
