// Multi-core: each core computes partial sum → workspace[blockIdx]
// Host reduces workspace after kernel returns
// Supports float32, float16

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelSnrm2 {
public:
    __aicore__ inline KernelSnrm2() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR workspace,
                                 int64_t totalLength, int64_t incx,
                                 int64_t tileLength, int64_t numCores,
                                 int64_t chunkSize, int64_t needCast)
    {
        this->totalLength = totalLength;
        this->incx = incx;
        this->tileLength = tileLength;
        this->numCores = numCores;
        this->chunkSize = chunkSize;
        this->needCast = needCast;

        int64_t physCount = tileLength * incx;

        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), totalLength * incx);
        wsGm.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(workspace), numCores);

        // UB: input buffer (double-buffered, physCount elements)
        pipe.InitBuffer(inQueueX, BUFFER_NUM, physCount * sizeof(T));

        // UB: squaring buffer (physCount float32 elements)
        pipe.InitBuffer(sqBuf, physCount * sizeof(float));

        // UB: cast buffer for fp16→fp32
        if (this->needCast != 0) {
            pipe.InitBuffer(castBuf, physCount * sizeof(float));
        }

        // UB: partial sum buffer
        pipe.InitBuffer(sumBuf, 16 * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        // Compute this block's chunk range
        int64_t blockIdx = static_cast<int64_t>(AscendC::GetBlockIdx());
        int64_t localStart = blockIdx * this->chunkSize;
        int64_t localEnd = localStart + this->chunkSize;
        if (localEnd > this->totalLength) {
            localEnd = this->totalLength;
        }
        int64_t localN = localEnd - localStart;

        float partialSum = 0.0f;

        if (localN > 0) {
            int64_t tileNum = (localN + this->tileLength - 1) / this->tileLength;

            for (int64_t i = 0; i < tileNum; ++i) {
                int64_t tileStart = i * this->tileLength;
                int64_t curTileLen = this->tileLength;
                if (i == tileNum - 1) {
                    curTileLen = localN - tileStart;
                }
                int64_t physCount = curTileLen * this->incx;

                CopyIn(localStart + tileStart, physCount);
                float tileSum = Compute(curTileLen, physCount);
                partialSum += tileSum;
            }
        }

        // Write partial sum to workspace[blockIdx]
        WriteWorkspace(partialSum);
    }

private:
    __aicore__ inline void CopyIn(int64_t tileStart, int64_t physCount)
    {
        int64_t gmOffset = tileStart * this->incx;

        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(physCount * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
        AscendC::DataCopyPad(xLocal, xGm[gmOffset], copyParams, padParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline float Compute(int64_t curTileLen, int64_t physCount)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<float> sqLocal = sqBuf.Get<float>();

        float tileSum = 0.0f;

        if (this->incx == 1) {
            // Contiguous case: vectorized Mul + ReduceSum
            AscendC::LocalTensor<float> xFloat;
            if constexpr (std::is_same_v<T, float>) {
                xFloat = xLocal.ReinterpretCast<float>();
            } else {
                xFloat = castBuf.Get<float>();
                AscendC::Cast(xFloat, xLocal, AscendC::RoundMode::CAST_NONE,
                              static_cast<uint32_t>(curTileLen));
            }

            AscendC::Mul(sqLocal, xFloat, xFloat, static_cast<uint32_t>(curTileLen));

            AscendC::LocalTensor<float> sumLocal = sumBuf.Get<float>();
            const uint32_t reduceShape[2] = {1U, static_cast<uint32_t>(curTileLen)};
            AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
                sumLocal, sqLocal, sqLocal[0], reduceShape, true);

            tileSum = sumLocal.GetValue(0);
        } else {
            // Strided case: GetValue for strided access
            AscendC::LocalTensor<float> xFloat;
            if constexpr (std::is_same_v<T, float>) {
                xFloat = xLocal.ReinterpretCast<float>();
            } else {
                xFloat = castBuf.Get<float>();
                AscendC::Cast(xFloat, xLocal, AscendC::RoundMode::CAST_NONE,
