// Snrm2 op_host — tiling + kernel launch + host-side workspace reduction
// Single kernel launch, multi-core. Each core computes partial sum → workspace[coreIdx]
// Host reduces workspace entries after synchronous kernel returns.

#include <algorithm>
#include <cmath>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_snrm2_float.h"
#include "aclrtlaunch_snrm2_half.h"

namespace ascend_kernel {

at::Tensor snrm2(const at::Tensor &x, int64_t n, int64_t incx)
{
    TORCH_CHECK(x.dim() == 1, "x must be 1D");
    TORCH_CHECK(n >= 0, "n must be non-negative");
    TORCH_CHECK(incx >= 1, "incx must be >= 1");
    TORCH_CHECK(x.numel() >= n * incx, "x too small for n*incx");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf,
        "x must be float32 or float16");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    // Handle n == 0 edge case
    if (n == 0) {
        auto output = at::zeros({}, x.options());
        return output.squeeze(-1);
    }

    // Platform info
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    if (coreNum <= 0) {
        coreNum = 32;
    }

    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    int64_t dtypeSize = static_cast<int64_t>(x.element_size());
    int64_t needCast = (dtypeSize == 2) ? static_cast<int64_t>(1) : static_cast<int64_t>(0);

    // Core count: use fewer cores for small n to avoid overhead
    int64_t numCores = std::min(coreNum, n > 0 ? n : static_cast<int64_t>(1));
    int64_t chunkSize = (n + numCores - 1) / numCores;

    // Tiling: UB allocation
    // For float32: 2*input (double buffer) + 1*sq + 1*sum ≈ 4x of physCount*4 + small sumBuf
    // For float16: 2*input + 1*sq + 1*cast + 1*sum ≈ 5x
    int64_t physTileBytesPerElem;
    if (needCast != 0) {
        // fp16: inQueue(2*2B) + sq(4B) + cast(4B) = 12B per phys elem + overhead
        physTileBytesPerElem = 12;
    } else {
        // fp32: inQueue(2*4B) + sq(4B) = 12B per phys elem + overhead
        physTileBytesPerElem = 12;
    }

    // Safe tile size: divide UB by per-element bytes, with headroom
    int64_t safeUbSize = static_cast<int64_t>(ubSize) * 70 / 100;  // 70% UB for tile data
    int64_t physTileSize = safeUbSize / physTileBytesPerElem;

    // Logical tile size = physTileSize / incx
    int64_t tileLength = physTileSize / incx;
    if (tileLength < 32) {
        tileLength = 32;  // Minimum tile for efficiency
    }
    tileLength = std::min(tileLength, n);

    // Output: scalar tensor
    auto output = at::empty({}, x.options());

    // Workspace: one float32 per core for partial sums
    auto workspace = at::empty({numCores}, at::TensorOptions().dtype(at::kFloat).device(x.device()));

    // All params as named left values (required by EXEC_KERNEL_CMD)
    uint32_t blockDim = static_cast<uint32_t>(numCores);
    int64_t totalLength = n;
    int64_t strideVal = incx;
    int64_t tileLen = tileLength;
    int64_t coreCnt = numCores;
    int64_t chunkSz = chunkSize;
    int64_t castFlag = needCast;
    uint32_t workspaceShift = 0;

    // Launch kernel with blockDim cores
    if (x.scalar_type() == at::kHalf) {
        EXEC_KERNEL_CMD(snrm2_half, blockDim,
                        x, workspace,
                        totalLength, strideVal, tileLen, coreCnt, chunkSz, castFlag);
    } else {
        EXEC_KERNEL_CMD(snrm2_float, blockDim,
                        x, workspace,
                        totalLength, strideVal, tileLen, coreCnt, chunkSz, castFlag);
    }

    // Host-side reduction: workspace is now filled
    auto wsCpu = workspace.cpu();
    auto wsAcc = wsCpu.accessor<float, 1>();
    float globalSum = 0.0f;
    for (int64_t i = 0; i < numCores; ++i) {
        globalSum += wsAcc[i];
    }
    float result = std::sqrt(globalSum);

    // Write result to output tensor
    if (x.scalar_type() == at::kHalf) {
        output[0] = static_cast<at::Half>(result);
    } else {
        output[0] = result;
    }

    return output;
}

}  // namespace ascend_kernel
