public:
    __aicore__ inline KernelSnrm2() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR workspace,
                                 int64_t totalLength, int64_t incx,
                                 int64_t tileLength, int64_t numCores,
                                 int64_t chunkSize, int64_t needCast)
    {
        this->totalLength = totalLength;
        this->incx = incx;
        this->tileLength = tileLength;
        this->numCores = numCores;
        this->chunkSize = chunkSize;
        this->needCast = needCast;

