    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();

        float tileSum = 0.0f;

        if (this->incx == 1) {
            // Contiguous case: read elements sequentially
            if constexpr (std::is_same_v<T, float>) {
                for (int64_t j = 0; j < curTileLen; ++j) {
                    float val = xLocal.GetValue(static_cast<int32_t>(j));
                    tileSum += val * val;
                }
            } else {
                AscendC::LocalTensor<float> xFloat = castBuf.Get<float>();
                AscendC::Cast(xFloat, xLocal, AscendC::RoundMode::CAST_NONE,
                              static_cast<uint32_t>(curTileLen));
                for (int64_t j = 0; j < curTileLen; ++j) {
                    float val = xFloat.GetValue(static_cast<int32_t>(j));
                    tileSum += val * val;
                }
            }
        } else {
            // Strided case: jump by incx in physical layout
            int64_t stride = this->incx;
            if constexpr (std::is_same_v<T, float>) {
                for (int64_t j = 0; j < curTileLen; ++j) {
                    int64_t physIdx = j * stride;
                    float val = xLocal.GetValue(static_cast<int32_t>(physIdx));
                    tileSum += val * val;
                }
            } else {
                AscendC::LocalTensor<float> xFloat = castBuf.Get<float>();
                AscendC::Cast(xFloat, xLocal, AscendC::RoundMode::CAST_NONE,
                              static_cast<uint32_t>(physCount));
                for (int64_t j = 0; j < curTileLen; ++j) {
                    int64_t physIdx = j * stride;
                    float val = xFloat.GetValue(static_cast<int32_t>(physIdx));
                    tileSum += val * val;
                }
            }
        }

        inQueueX.FreeTensor(xLocal);
        return tileSum;
    }

    __aicore__ inline void WriteWorkspace(float value)
    {
        AscendC::LocalTensor<float> sumLocal = sumBuf.Get<float>();
        sumLocal.SetValue(0, value);

        int64_t blockIdx = static_cast<int64_t>(AscendC::GetBlockIdx());
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(sizeof(float)), 0, 0, 0};
        AscendC::DataCopyPad(wsGm[blockIdx], sumLocal, copyParams);
    }

