    __aicore__ inline void CopyIn(int64_t tileStart, int64_t physCount)
    {
        int64_t gmOffset = tileStart * this->incx;

        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(physCount * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
        AscendC::DataCopyPad(xLocal, xGm[gmOffset], copyParams, padParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline float Compute(int64_t curTileLen, int64_t physCount)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();

        float tileSum = 0.0f;
        int64_t stride = this->incx;

        for (int64_t j = 0; j < curTileLen; ++j) {
            int64_t physIdx = j * stride;
            T valRaw = xLocal.GetValue(static_cast<int32_t>(physIdx));

            float val;
            if constexpr (std::is_same_v<T, float>) {
                val = valRaw;
            } else {
                val = static_cast<float>(valRaw);
            }
            tileSum += val * val;
        }

        inQueueX.FreeTensor(xLocal);
        return tileSum;
    }

    __aicore__ inline void WriteWorkspace(float value)
    {
        AscendC::LocalTensor<float> sumLocal = sumBuf.Get<float>();
        sumLocal.SetValue(0, value);

        int64_t blockIdx = static_cast<int64_t>(AscendC::GetBlockIdx());
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(sizeof(float)), 0, 0, 0};
        AscendC::DataCopyPad(wsGm[blockIdx], sumLocal, copyParams);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<float> wsGm;

    int64_t totalLength;
    int64_t incx;
    int64_t tileLength;
    int64_t numCores;
    int64_t chunkSize;
};

